def compute(vars):
    values = [vars["v1"], vars["v2"], vars["v3"]]
    total = sum(values)
    count = len(values)
    try:
        average = total / count
    except ZeroDivisionError:
        return None

    return {
        "value": average,
        "trace": {
            "values": values,
            "total": total,
            "count": count,
            "average": average,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
